    "content": "新华社东京10月17日电（记者李子越 陈泽安）据日本共同社17日报道，日本和美国将于19日至29日在日本多地开展“利剑27”大规模联合军演，投入兵力总计接近6万人，引发日本国内广泛担忧与反对。 报道称，此次演习是涵盖陆海空各部队的综合性训练，日本自卫队和美军将分别投入约4.5万人和1.2万人。此外，澳大利亚、加拿大、法国、德国、荷兰、新西兰和菲律宾等国也将参加，其中后5国为首次参与。 值得关注的是，日本政府今年3月不顾当地民众反对强行部署于熊本县的“25式地对舰导弹”将参加此次演习。该导弹将从熊本县转移至横跨长崎县…"
