    "content": "新华社北京10月17日电（记者李春宇、吴俊宽）17日，在2026年北京马拉松博览会上，国家体育总局运动医学研究所相关负责人现场宣介《路跑赛事大众选手健康风险防控》行业标准，涉及赛前风险筛查、赛中监测处置、赛后健康随访，旨在推动赛事健康保障从侧重事后急救向全过程管理转变。 该标准是国内首个聚焦路跑赛事大众选手健康风险防控的行业标准，已于今年9月15日起正式实施。运动医学研究所副所长厉彦虎说，近年来，国内路跑赛事快速发展，参与人群持续扩大，然而运动性猝死、急性心血管事件等情况时有发生，赛事医疗保障的技术流程和服务水平仍…"
