    "content": "新华社首尔10月17日电（记者黄昕欣）韩国外交部发言人17日发表谈话说，对于日本政府高层当天向供奉有二战甲级战犯的靖国神社献祭品及前往参拜，韩国政府再次表示“深切失望和遗憾”。 谈话说，韩国政府敦促日本政府高层正视历史，以实际行动展现对历史的虚心反思和真诚反省。韩国政府再次强调，这是构建以国家间和国民间相互信任为基础、面向未来的韩日关系的重要基石。 据日本媒体报道，靖国神社17日起举行为期3天的秋季大祭。日本经济财政政策担当大臣城内实17日上午参拜靖国神社。当天，日本首相高市早苗以“内阁总理大臣”名义，向靖国神社供…"
