    "title": "朱子学与多元文明对话大会暨第五届考亭论坛在福建南平启幕",
    "link": "https://www.chinanews.com.cn/sh/2026/10-17/10716275.shtml",
    "pub_date": "2026-10-17 17:04:44",
    "author": "",
    "description": "中新网南平10月17日电 (陈悦 张丽君 吴冠标)考亭故里，文脉绵延。朱子学与多元文明对话大会暨第五届考亭论坛于17日至18日在福建南平举办。本次大会由中国社会科学院、国际儒学联合会、福建省人民政府联合主办，论坛以“明理崇礼，知行相须——文明对话与人类社会秩序构建”为主题，近两百位海内外专家学者齐聚于此，展开一场跨越时空的文明对话。",
    "content": "中新网南平10月17日电 (陈悦 张丽君 吴冠标)考亭故里，文脉绵延。朱子学与多元文明对话大会暨第五届考亭论坛于17日至18日在福建南平举办。本次大会由中国社会科学院、国际儒学联合会、福建省人民政府联合主办，论坛以“明理崇礼，知行相须——文明对话与人类社会秩序构建”为主题，近两百位海内外专家学者齐聚于此，展开一场跨越时空的文明对话。"
