    "description": "中新网上海10月17日电 (记者 缪璐)10月16日，2026别克LPGA锦标赛展开第二轮角逐，起风后的佘山国际高尔夫俱乐部难度大增。韩国球员崔慧珍(Hye-Jin Choi)本轮交出74杆，以总成绩-6杆继续领跑，中国球员殷若宁与卫冕冠军、泰国球员吉诺·提提库(Jeeno Thitikul)以总成绩-2杆位于并列第7位。",
