    "content": "新华社北京10月17日电 特稿｜风险动荡加剧 经济承压前行——全球面临新的“增长之问” 新华社记者宿亮 地缘冲突扰动全球能源供应，高债务与高融资成本挤压经济增长空间，人工智能（AI）在创造增长机遇的同时也带来新的不确定性……当前，世界经济面临着多重风险交织、相互传导的复杂局面。 在国际货币基金组织（IMF）和世界银行集团年会期间，与会人士围绕全球经济前景、债务负担和技术变革等议题展开讨论。如何在冲击不断、增长分化的环境中维护经济稳定、拓展发展空间，成为一道亟待回答的“增长之问”。 地缘冲击让各国经济承压 “一台联合…"
