    "content": "新华社昆明10月17日电 题：云南楚雄：加速推动基层医疗服务向“优”向“强” 新华社记者王安浩维 “以前肚子疼，去县里看病又远又麻烦，总想着忍忍就过去。现在镇里卫生院就能做胃肠镜，还有县医院的专家检查，心里踏实多了。”在云南省楚雄彝族自治州姚安县光禄镇中心卫生院，村民王天育多年的胃溃疡，终于在家门口得到系统性检查。 像王天育一样，楚雄州越来越多的山区群众，正在家门口享受到更优质、便捷的医疗服务。 武定县大雪坡村村民白吉盛在昆明务工，母亲因血管问题需紧急手术，需要转到上级医疗机构。正在他发愁之际，乡镇卫生院的电话就来…"
