    "content": "新华社呼和浩特10月17日电（记者安路蒙、王雪冰）联合国粮食及农业组织（粮农组织）15日在意大利罗马宣布，中国治沙人殷玉珍入选首届“联合国粮农组织农业粮食体系与农村发展百位巾帼英雄”，作为榜单第100位入选者隆重登场。颁奖现场，美国友人赛考斯难掩激动，为这位相识26年的老朋友热烈鼓掌。 从毛乌素沙地深处的一名普通农村妇女，到站上国际舞台讲述中国治沙故事的生态守护者，殷玉珍用40余年光阴，将约7万亩荒沙变为绿洲；一段跨越国界、中断26年的友谊，也在2026年重续前缘。 10月15日，殷玉珍在意大利罗马出席颁奖仪式。新…"
