    "content": "新华社日本名古屋10月17日电（记者郑直、张卉）中国体育代表团17日宣布，女子残疾人跆拳道运动员李羽洁和男子残疾人举重运动员闫盼盼将担任爱知·名古屋亚残运会开幕式中国体育代表团旗手。 李羽洁2023年起在北京体育大学运动训练专业在读。她曾在2019年获得世界残疾人跆拳道锦标赛（土耳其）女子K44级58公斤级金牌。2021年李羽洁获得东京残奥会该级别铜牌，这也是中国体育代表团残奥会跆拳道项目历史首枚奖牌。2023年杭州亚残运会，她夺得女子K44级57公斤级铜牌，随后在世界残疾人跆拳道大奖赛总决赛夺得金牌。2024年巴…"
