    "content": "新华社北京10月17日电 题：15个省份大到暴雨 降雨进入最强时段 新华社记者刘诗平 中央气象台17日预报，受较强冷空气影响，我国出现大范围雨雪、大风、降温天气，17日迎来最强降雨时段，15个省份有大到暴雨，部分地区有大暴雨。气象专家提醒，本次天气过程降雨范围广、局地降雨强、北方地区大风降温显著，公众需注意御寒保暖和交通安全。 迎来最强降雨时段 中央气象台17日早晨同时发布大风蓝色预警、暴雨蓝色预警和强对流天气蓝色预警。预计17日白天到夜间是本轮大范围降雨的最强降雨时段。内蒙古中东部、黑龙江西南部、吉林西部、辽宁大…"
