    "title": "纪录片《新长征路上的我们》主题曲《光芒》MV",
    "link": "http://www.news.cn/20261017/374a1f41173b4e6980d46e59cdaf15f2/c.html",
    "pub_date": "2026-10-17 15:10:52",
    "author": "邱晨,陶冶,刘洋",
    "description": "“纪念长征胜利90周年”纪录片《新长征路上的我们》主题曲《光芒》正式上线。以青春之声回望壮阔远征，持赤诚信念书写时代华章。 往昔，先辈穿越重关险隘，于绝境之中铸就奇迹。 今朝，我们承接先辈精神，踏遍山河、奔赴前路，共创未来。 那些搏击巨浪、冲破险阻的身影，凝成指引前路的恒久光亮。“我追光芒，不负光芒。以心中信仰，续写荣光。” 演唱：黄子弘凡 作词/作曲：石一岑 制作人：亢竹青@TME制作人联盟 编曲：岑思源 出品人：张平锋 杨玲 曾志中…",
