    "author": "王冠森,朱高祥,唐榕苓",
    "description": "新华社昆明10月17日电（记者王冠森、朱高祥）2026年“铸牢共同体 中华一家亲”主题宣传活动云南集中采访于10月17日在昆明启动。 本次活动将紧扣铸牢中华民族共同体意识主线，深入宣传云南学习贯彻民族团结进步促进法，构筑共有精神家园、促进交往交流交融、推动共同繁荣发展的生动实践。采访团将走进社区村寨、田间地头、民族博物馆，记录各民族守望相助、和谐共处的动人故事，展现云南各族群众一心向党、团结奋斗，推进边疆地区经济社会发展取得的成绩。 本…",
