    "content": "新华社联合国10月16日电 中国裁军事务大使李驰江16日在联大第一委员会作关于核问题答辩发言时表示，中方坚决反对一些国家歪曲抹黑中国核政策和国防力量建设的错误言论。 李驰江强调，中国在核武器问题上历来采取极其慎重、负责的态度。从拥有核武器第一天起，中国就倡导全面禁止和彻底销毁核武器，承诺在任何时候和任何情况下都不首先使用核武器，无条件承诺不对无核武器国家和无核武器区使用或威胁使用核武器，始终把核力量维持在国家安全需要的最低水平。中国核力量同美俄完全不在一个量级，现阶段要求中方参加所谓中美俄三边核裁军谈判不公平、不合…"
