    "content": "从“买中国货”到“帮中国货卖到全世界”——这是第140届广交会现场采购商用订单投出的信任票。 一副眼镜，能翻译 122 种语言，开展首日展台前就排起了各国采购商的长队。而这样的“爆款”，在本届广交会不是个案——服务机器人、智慧医疗、新能源等新兴未来产业新品增长约 20%。数字背后，是中国先进制造业集体向上的底气。 一件件“爆款”背后，更是中国先进制造业越来越清晰的自信。这种自信，来自技术与创新：64%的参展企业用上了工业互联网和人工智能；新产品占比 23.2%，创历史新高；这种自信，同样来自外国客商的认可：已有近2…"
