    "author": "李佳旭,谭慧婷",
    "description": "新华社巴拿马城10月16日电 布里奇敦消息：第8批中国援巴巴多斯医疗队近日在巴伊丽莎白女王医院完成该国首例血管内超声指导下前降支齐头慢性完全闭塞病变开通手术，推动当地复杂冠脉介入诊疗技术取得新进展。 医疗队队长崔坤介绍，患者为一名长期受心绞痛困扰的54岁男性，其前降支近端存在齐头慢性完全闭塞，介入治疗难度较高。受当地医疗条件限制，患者若接受冠脉搭桥手术，需等候较长时间，面临心肌缺血带来的病痛与风险。经评估，医疗队实施血管内超声指导下的介…",
    "content": "新华社巴拿马城10月16日电 布里奇敦消息：第8批中国援巴巴多斯医疗队近日在巴伊丽莎白女王医院完成该国首例血管内超声指导下前降支齐头慢性完全闭塞病变开通手术，推动当地复杂冠脉介入诊疗技术取得新进展。 医疗队队长崔坤介绍，患者为一名长期受心绞痛困扰的54岁男性，其前降支近端存在齐头慢性完全闭塞，介入治疗难度较高。受当地医疗条件限制，患者若接受冠脉搭桥手术，需等候较长时间，面临心肌缺血带来的病痛与风险。经评估，医疗队实施血管内超声指导下的介入手术，成功开通闭塞血管。 巴巴多斯高血压、糖尿病多发，冠心病发病率较高，当地冠…"
