    "description": "中新网兰州10月17日电 (记者 冯志军)一次重要会议、一棵百年老树、一首经典诗篇、一场联欢晚会、一场惨烈战役、一个交汇点、一首胜利之歌……91年后，在甘肃定西市通渭县榜罗镇，有关中国工农红军过境和中共中央政治局在此召开重要会议的十件往事，仍在当地被广泛传颂。",
    "content": "中新网兰州10月17日电 (记者 冯志军)一次重要会议、一棵百年老树、一首经典诗篇、一场联欢晚会、一场惨烈战役、一个交汇点、一首胜利之歌……91年后，在甘肃定西市通渭县榜罗镇，有关中国工农红军过境和中共中央政治局在此召开重要会议的十件往事，仍在当地被广泛传颂。"
