    "description": "新华社华盛顿10月16日电 专访丨IMF官员警告全球经济面临紧迫财政挑战 新华社记者熊茂伶 李睿 国际货币基金组织（IMF）财政事务部主任罗德里戈·巴尔德斯日前在接受新华社记者专访时表示，在高债务水平、更高利率以及不断增长的公共支出需求背景下，几乎所有经济体都面临紧迫的财政挑战。 他表示，债务高企是现实，对全球经济体而言，债务与国内生产总值（GDP）之比正在上升，利率比几年前更高，而且有很多增加的支出需求。“所有这些因素叠加在一起，财政…",
    "content": "新华社华盛顿10月16日电 专访丨IMF官员警告全球经济面临紧迫财政挑战 新华社记者熊茂伶 李睿 国际货币基金组织（IMF）财政事务部主任罗德里戈·巴尔德斯日前在接受新华社记者专访时表示，在高债务水平、更高利率以及不断增长的公共支出需求背景下，几乎所有经济体都面临紧迫的财政挑战。 他表示，债务高企是现实，对全球经济体而言，债务与国内生产总值（GDP）之比正在上升，利率比几年前更高，而且有很多增加的支出需求。“所有这些因素叠加在一起，财政政策面临严峻挑战。” 根据14日发布的IMF最新一期《财政监测报告》，全球公共债…"
