    "pub_date": "2026-10-17 12:43:40",
    "author": "",
    "description": "中新网北京10月17日电(记者 国璇) 2026中国户外运动产业大会16日晚在北京市昌平区开幕，会上发布了《中国户外运动产业发展报告(2025-2026)》(以下简称“报告”)。报告显示，截至2025年底，我国户外运动参与人数超过5亿，户外运动相关产业总规模约3.17万亿元人民币。",
    "content": "中新网北京10月17日电(记者 国璇) 2026中国户外运动产业大会16日晚在北京市昌平区开幕，会上发布了《中国户外运动产业发展报告(2025-2026)》(以下简称“报告”)。报告显示，截至2025年底，我国户外运动参与人数超过5亿，户外运动相关产业总规模约3.17万亿元人民币。"
