    "content": "新华社北京10月17日电 面对沙特阿拉伯指控伊朗“煽动”也门胡塞武装近期频繁袭击沙特，伊朗外交部16日否认伊方与胡塞武装袭击沙特有关。 伊朗外交部发言人伊斯梅尔·巴加埃在声明中说，伊朗否认关于“伊朗在胡塞武装行动中发挥作用”的任何说法，胡塞武装依据自身利益和判断行事。对熟悉伊朗与盟友关系的人来说，那种说法不可信。 10月12日，在伊朗首都德黑兰，伊朗外交部发言人巴加埃出席例行记者会。新华社记者沙达提摄 巴加埃同时强调，伊方认为局势紧张不符合任何一方的利益。伊朗有意在沙特与胡塞武装之间斡旋，“一直致力于通过斡旋帮助（…"
