    "description": "新华社雅加达10月17日电（记者 张怡晟）记者从中国铁路国际有限公司获悉，截至17日，印尼雅万高铁正式开通运营满三年，累计开行动车组列车58666列，发送旅客超1800万人次，安全运行超890万公里，正点率达99.4%。 三年来，中印尼运营团队结合客流增长动态优化调整列车运行图，加大高铁动车组列车开行力度，日均开行列车由开通初期的14列增至高峰期的62列，单日最高旅客发送量26770人次。雅万高铁建设运营主体印尼中国高速铁路有限公司（K…",
    "content": "新华社雅加达10月17日电（记者 张怡晟）记者从中国铁路国际有限公司获悉，截至17日，印尼雅万高铁正式开通运营满三年，累计开行动车组列车58666列，发送旅客超1800万人次，安全运行超890万公里，正点率达99.4%。 三年来，中印尼运营团队结合客流增长动态优化调整列车运行图，加大高铁动车组列车开行力度，日均开行列车由开通初期的14列增至高峰期的62列，单日最高旅客发送量26770人次。雅万高铁建设运营主体印尼中国高速铁路有限公司（KCIC）客户满意度调查显示，客户总体满意度达95.79%。 雅万高铁开通运营以来…"
