    "author": "张研,陈弘毅",
    "description": "今年9月6日，G3998次复兴号列车驶出瑞金站，奔向千里之外的延安。当年，革命先辈爬雪山、过草地，奋进远征之途；今天，钢铁动脉连通红色热土，便利了群众出行、激活了地方产业，铺就老区发展振兴的快车道。 “要永远铭记老区人民为革命作出的贡献，永远不要忘记老区，永远不要忘记老区人民。”在红军长征胜利90周年之际，重温习近平总书记对老区人民的深情牵挂，更能深刻理解共产党人的价值追求和初心使命。 老区，是中国人民选择和拥护中国共产党的历史见证。这…",
    "content": "今年9月6日，G3998次复兴号列车驶出瑞金站，奔向千里之外的延安。当年，革命先辈爬雪山、过草地，奋进远征之途；今天，钢铁动脉连通红色热土，便利了群众出行、激活了地方产业，铺就老区发展振兴的快车道。 “要永远铭记老区人民为革命作出的贡献，永远不要忘记老区，永远不要忘记老区人民。”在红军长征胜利90周年之际，重温习近平总书记对老区人民的深情牵挂，更能深刻理解共产党人的价值追求和初心使命。 老区，是中国人民选择和拥护中国共产党的历史见证。这份厚重的老区情怀，饱含着对土地与人民的赤诚眷恋，蕴藏着对苦难与辉煌的深刻体悟，是…"
