    "author": "南方周末记者 赵继林",
    "description": "特斯拉明确标注，火箭版未获准在公共道路行驶。 南方周末记者 赵继林 责任编辑：冯叶 当地时间2026年10月15日，美国得克萨斯州麦格雷戈，特斯拉公司发布其全新一代Roadster电动跑车。该画面截取自10月16日特斯拉发布的直播视频。视觉中国/图 时隔近9年，特斯拉新款跑车终于来了。 2026年10月16日，特斯拉在美国得克萨斯州举行Roadster发布活动，展示了推迟已久的第二代Roadster跑车。目前，该款车型已经可以在特斯拉中…",
    "content": "特斯拉明确标注，火箭版未获准在公共道路行驶。 特斯拉的飞行汽车方案，本质上是在顶级超跑上“加装”飞行模块，而国内主流厂商则是在设计“会飞的交通工具”。 “核心问题是这样的汽车生产出来，应用场景在哪里，市场用户在哪里，除发烧友之外，能否进入家庭？” 南方周末记者 赵继林 责任编辑：冯叶 当地时间2026年10月15日，美国得克萨斯州麦格雷戈，特斯拉公司发布其全新一代Roadster电动跑车。该画面截取自10月16日特斯拉发布的直播视频。视觉中国/图 时隔近9年，特斯拉新款跑车终于来了。 2026年10月16日，特斯拉…"
