    "description": "新华社吉隆坡10月17日电 记者手记｜传统文化在马来西亚的相遇和交融 新华社记者王嘉伟 “原来我属羊！”在得知自己的中国生肖属相后，马来西亚女孩埃祖林拿起毛笔，照着纸上的模板，一笔一画地写起了“羊”字。一旁属龙的阿齐拉面对笔画复杂的繁体“龍”字端详了许久，才小心翼翼地开始临摹。 这是记者近日在马来西亚首都吉隆坡一场文化活动中看到的场景。成功写出“龍”字后，阿齐拉很有成就感地向大家展示自己的作品。 阿齐拉向记者介绍说，像中国一样，马来西亚…",
    "content": "新华社吉隆坡10月17日电 记者手记｜传统文化在马来西亚的相遇和交融 新华社记者王嘉伟 “原来我属羊！”在得知自己的中国生肖属相后，马来西亚女孩埃祖林拿起毛笔，照着纸上的模板，一笔一画地写起了“羊”字。一旁属龙的阿齐拉面对笔画复杂的繁体“龍”字端详了许久，才小心翼翼地开始临摹。 这是记者近日在马来西亚首都吉隆坡一场文化活动中看到的场景。成功写出“龍”字后，阿齐拉很有成就感地向大家展示自己的作品。 阿齐拉向记者介绍说，像中国一样，马来西亚不同族群传承着各自的书法艺术。她认为，让年轻一代有机会接触和体验不同文化，对于文…"
