    "description": "新华社郑州10月17日电 题：“豆腐姑娘”李福贵：做一株崖上的太行菊 新华社记者王前慧 中秋节前，李福贵决定上山去再看看村里的老人。 她准备了300份牛奶、香蕉和月饼，开着车往太行山深处去。这里的人几乎都认得她，一声清亮的“打豆腐嘞来啦——”，在太行山里反复回响。也因为这句话，网友叫她“豆腐姑娘”。 这条路，她太熟悉了，这几年走了好几百趟。 李福贵正在把给老人准备的礼品装车。（受访者供图） 她本名叫李亚云，网名叫“李福贵”。她说，这是她…",
    "content": "新华社郑州10月17日电 题：“豆腐姑娘”李福贵：做一株崖上的太行菊 新华社记者王前慧 中秋节前，李福贵决定上山去再看看村里的老人。 她准备了300份牛奶、香蕉和月饼，开着车往太行山深处去。这里的人几乎都认得她，一声清亮的“打豆腐嘞来啦——”，在太行山里反复回响。也因为这句话，网友叫她“豆腐姑娘”。 这条路，她太熟悉了，这几年走了好几百趟。 李福贵正在把给老人准备的礼品装车。（受访者供图） 她本名叫李亚云，网名叫“李福贵”。她说，这是她对未来的期许。 去年夏天，她因记录自己进山卖货的视频走红。 福贵的视频内容很淳朴…"
