    "title": "摩根士丹利：明年超大规模及新兴云厂商数据中心新增算力将同比激增48%",
    "link": "https://36kr.com/newsflashes/4029287613485702?f=rss",
    "pub_date": "2026-10-17 11:36:15",
    "author": "",
    "description": "据报道，摩根士丹利称，2027年，超大规模云厂商与新兴云的数据中心新增算力规模将同比激增48%，达到32吉瓦。谷歌、亚马逊、微软、Meta四大超大规模云厂商贡献约85%的新增建设量；2028年将再新增39吉瓦，同比扩张21%。（界面）",
