    "content": "新华社沈阳10月17日电（记者刘艺淳）岁岁重阳，今又重阳。82岁的丁明，常被问到一个问题：“您还能跨栏？” 回答很干脆：“岁数从来不是拦着运动的坎儿。” 不久前在韩国大邱举办的第26届世界大师田径锦标赛上，辽宁鞍山大爷丁明在M80组别（80-84岁年龄组）男子80米栏决赛上，跑出15秒99夺冠，将此前由日本选手保持的亚洲纪录提高半秒多。 丁明（中）在第26届世界大师田径锦标赛M80组别男子80米栏决赛赛场上 在外人眼中，他是驰骋赛场的耄耋“飞人”。在丁明看来，竞技成绩只是“附加收获”，把运动当作吃饭、睡觉一样才值得…"
