    "author": "朱雨博",
    "description": "新华社圣地亚哥10月16日电（记者朱雨博）由中国社会科学院与智利大学学者共同撰写的《中国和智利：制度互鉴与协同发展》16日在智利首都圣地亚哥正式发布，智利代外长帕特里西奥·托雷斯、中国驻智利大使牛清报及两国外交官、学界代表等百余人出席新书发布会。 该书汇集中智学者的12篇研究报告，从外交与贸易延伸至数字技术、南极科考、医学与音乐，在具体的人物、机构和实践中，呈现双边关系的历史纵深与社会基础。立足两国、放眼拉美，书中探讨不同发展经验相互启…",
    "content": "新华社圣地亚哥10月16日电（记者朱雨博）由中国社会科学院与智利大学学者共同撰写的《中国和智利：制度互鉴与协同发展》16日在智利首都圣地亚哥正式发布，智利代外长帕特里西奥·托雷斯、中国驻智利大使牛清报及两国外交官、学界代表等百余人出席新书发布会。 该书汇集中智学者的12篇研究报告，从外交与贸易延伸至数字技术、南极科考、医学与音乐，在具体的人物、机构和实践中，呈现双边关系的历史纵深与社会基础。立足两国、放眼拉美，书中探讨不同发展经验相互启发的可能，为理解中智关系、南南合作与现代化的多样路径提供思考。 托雷斯在发布会上…"
