    "author": "解统强",
    "description": "新华社西宁10月16日电（记者解统强）一口地道的青海湟源方言，从一位白发苍苍的美国老人口中说出，总能让初次见面的人惊讶不已。 他叫柏大卫，今年95岁，出生在美国纽约，却把人生中最纯粹的童年、最绵长的牵挂，都留在了青藏高原的丹噶尔古城——青海省西宁市湟源县。 1932年，尚在襁褓中的柏大卫随父母远渡重洋来到湟源，一住就是17年。古城的街巷印着他和各族伙伴奔跑的脚印，湟水的河滩留着他嬉闹的笑声。他跟着街坊学说话、跟着伙伴逛集市，一口湟源土话…",
    "content": "新华社西宁10月16日电（记者解统强）一口地道的青海湟源方言，从一位白发苍苍的美国老人口中说出，总能让初次见面的人惊讶不已。 他叫柏大卫，今年95岁，出生在美国纽约，却把人生中最纯粹的童年、最绵长的牵挂，都留在了青藏高原的丹噶尔古城——青海省西宁市湟源县。 1932年，尚在襁褓中的柏大卫随父母远渡重洋来到湟源，一住就是17年。古城的街巷印着他和各族伙伴奔跑的脚印，湟水的河滩留着他嬉闹的笑声。他跟着街坊学说话、跟着伙伴逛集市，一口湟源土话说得比本地人还顺溜。当年青海流传着一句俏皮童谣：“美国洋人大鼻子，爱吃中国的酿皮…"
