    "content": "新华社利雅得10月16日电（记者罗晨、王海洲）据沙特阿拉伯通讯社16日报道，沙特2027年亚洲杯足球赛组委会表示，赛事筹备工作正按既定时间表推进。 该届赛事定于2027年1月7日至2月5日在沙特举行。此前据法新社报道，亚足联主席萨尔曼近日在瑞士接受采访时表示，亚足联正密切关注沙特局势，如有必要，或将该赛事推迟到2028年。 组委会强调，各项组织和运营筹备工作正按照既定时间表推进，包括做好比赛场馆、设施及配套服务的准备工作，为来自亚洲各地的参赛球队、球迷和媒体代表提供完善的赛事服务。 组委会重申，将继续开展相关工作，…"
