    "content": "新华社利马10月16日电（记者王植樱 廖思维）秘鲁总统藤森庆子16日呼吁民众做好准备，应对秘鲁数十年来“前所未见”的厄尔尼诺事件。 藤森庆子当天在秘鲁北部皮乌拉省视察防灾工作。她说：“各项指标和统计数据表明，秘鲁将迎来一次超强厄尔尼诺事件，这是数十年来前所未见的。” 她呼吁民众积极配合防灾工作，表示民众可以通过提前加固房屋、避免向河道倾倒垃圾以及了解疏散路线等方式做好预防工作。她同时强调只有通过团结协作，才能有效应对这场危机。 此前，藤森庆子15日宣布，将在全国易受灾地区开展一系列预防行动，以降低灾害风险，并优先处…"
