    "author": "范培珅,崔翰超,张智敏",
    "description": "新华社兰州10月17日电（记者崔翰超、张智敏）奇峰险峻，层林尽染，隘口下清流潺潺不绝。这里是甘肃省甘南藏族自治州迭部县腊子口镇，腊子口战役纪念馆就坐落在这青山绿水中。 腊子口，藏语意为“险绝的山谷峡口”，峡谷两侧山崖陡峭如刀削斧劈，易守难攻。 1935年9月，中国工农红军进入甘肃境内，为打开北上通道，发起了具有重要意义的腊子口战役。这场战役是红军长征进入甘肃关键性的一场硬仗，也是军事史上以弱胜强、出奇制胜的著名战役。腊子口战役的胜利，粉…",
    "content": "新华社兰州10月17日电（记者崔翰超、张智敏）奇峰险峻，层林尽染，隘口下清流潺潺不绝。这里是甘肃省甘南藏族自治州迭部县腊子口镇，腊子口战役纪念馆就坐落在这青山绿水中。 腊子口，藏语意为“险绝的山谷峡口”，峡谷两侧山崖陡峭如刀削斧劈，易守难攻。 1935年9月，中国工农红军进入甘肃境内，为打开北上通道，发起了具有重要意义的腊子口战役。这场战役是红军长征进入甘肃关键性的一场硬仗，也是军事史上以弱胜强、出奇制胜的著名战役。腊子口战役的胜利，粉碎了国民党部队企图阻挡红军北上的阴谋。 过去，红军勇夺天险，为中国革命的未来前赴…"
