    "description": "新华社波兰索波特10月17日电（记者王奕涵）匈牙利经济学家科莫罗茨基·伊什特万日前在出席第15届欧洲新思想论坛时表示，欧中在全球市场上虽存在竞争，但这并不妨碍彼此保持良好关系，双方应在公平竞争中相互学习，加强对话与合作。 科莫罗茨基在接受新华社记者采访时表示，面对复杂多变的国际形势，欧中更应坦诚交换意见，围绕具体问题开展务实商谈。 科莫罗茨基认为，欧中在汽车、能源等领域具有较好的合作基础和发展空间。他不久前途经匈牙利南部时，看到当地正在…",
    "content": "新华社波兰索波特10月17日电（记者王奕涵）匈牙利经济学家科莫罗茨基·伊什特万日前在出席第15届欧洲新思想论坛时表示，欧中在全球市场上虽存在竞争，但这并不妨碍彼此保持良好关系，双方应在公平竞争中相互学习，加强对话与合作。 科莫罗茨基在接受新华社记者采访时表示，面对复杂多变的国际形势，欧中更应坦诚交换意见，围绕具体问题开展务实商谈。 科莫罗茨基认为，欧中在汽车、能源等领域具有较好的合作基础和发展空间。他不久前途经匈牙利南部时，看到当地正在建设的比亚迪汽车工厂，对其印象深刻。他说，受地缘政治局势等因素影响，欧洲能源供应…"
