    "author": "魏冠宇,栗雅婷",
    "description": "新华社天津10月17日电（记者魏冠宇、栗雅婷）《中国职业教育白皮书》显示，我国技能人才支撑能力全面增强。2025年，全国高等职业教育毕业生582.04万人，中等职业教育毕业生521.82万人；近年年均向各行各业输送近千万名高素质劳动者和技能人才，新增劳动力平均受教育年限达14.35年。 这一白皮书10月17日在2026年世界职业技术教育发展大会上发布。 根据白皮书，我国中等、高等职业教育近年来每年分别为约500万初中毕业生、近600万适…",
    "content": "新华社天津10月17日电（记者魏冠宇、栗雅婷）《中国职业教育白皮书》显示，我国技能人才支撑能力全面增强。2025年，全国高等职业教育毕业生582.04万人，中等职业教育毕业生521.82万人；近年年均向各行各业输送近千万名高素质劳动者和技能人才，新增劳动力平均受教育年限达14.35年。 这一白皮书10月17日在2026年世界职业技术教育发展大会上发布。 根据白皮书，我国中等、高等职业教育近年来每年分别为约500万初中毕业生、近600万适龄青年提供接受高中阶段、高等教育机会，每年有近300万个家庭通过职业教育有了第一…"
